INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 216-B', '(Registro não autorizado de intimidade com IA ou ambiente digital. Alterado pela Lei nº 15.487, de 6 de agosto de 2026)', 2026, 'Ago', 'Ago/2026', 'Agosto', 8, 'Pena - detenção, de 6 (seis) meses a 1 (um) ano, e multa.', 'Art. 216-B. Produzir, fotografar, filmar ou registrar, por qualquer meio, conteúdo com cena de nudez ou ato sexual ou libidinoso de caráter privado sem autorização dos participantes: Pena - reclusão, de 2 (dois) a 6 (seis) anos, e multa. § 2º A pena aumenta-se de 1/3 (um terço) a 2/3 (dois terços) se o crime é cometido por meio de inteligência artificial, rede social ou em ambiente digital. (Redação dada pela Lei nº 15.487, de 2026)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15487.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 217-A', '(Estupro de vulnerável - Majorante para crimes praticados com inteligência artificial ou ambiente virtual. Alterado pela Lei nº 15.487, de 6 de agosto de 2026)', 2026, 'Ago', 'Ago/2026', 'Agosto', 8, 'Sem previsão expressa de causa de aumento para ambiente digital ou simulação com inteligência artificial.', '§ 6º Aumenta-se a pena de 1/3 (um terço) a metade se o crime é praticado com uso de inteligência artificial, criação de perfil falso, ambiente digital ou rede social para seduzir, induzir ou aliciar a vítima. (Incluído pela Lei nº 15.487, de 2026)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15487.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 218-C', '(Divulgação de cena de estupro ou sexo criada ou adulterada por inteligência artificial. Alterado pela Lei nº 15.487, de 6 de agosto de 2026)', 2026, 'Ago', 'Ago/2026', 'Agosto', 8, 'Pena - reclusão, de 1 (um) a 5 (cinco) anos, se o fato não constitui crime mais grave.', '§ 3º A pena é aumentada de 1/3 (um terço) a 2/3 (dois terços) se a imagem ou representação foi criada ou adulterada por tecnologia digital ou sistema de inteligência artificial. (Redação dada pela Lei nº 15.487, de 2026)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15487.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 226', '(Causa de aumento geral para crimes contra dignidade sexual por meio de internet ou IA. Alterado pela Lei nº 15.487, de 6 de agosto de 2026)', 2026, 'Ago', 'Ago/2026', 'Agosto', 8, 'A pena é aumentada: IV - de 1/3 (um terço), se o crime é cometido com o concurso de 2 (duas) ou mais pessoas.', 'Art. 226. A pena é aumentada: V - de metade a 2/3 (dois terços), se o crime é cometido por meio de rede mundial de computadores, rede social, aplicativo de mensagens ou com a utilização de inteligência artificial para dissimular a identidade do agente. (Incluído pela Lei nº 15.487, de 2026)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15487.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 92', '(§ 4º Na hipótese da reincidência descrita no § 3º deste artigo, o administrador, direta ou indiretamente responsável pela infração cometida, será interditado para o exercício do comércio pelo período de 5 cinco anos. Incluído pela Lei nº 15.358, de 14 de janeiro de 2026)', 2026, 'Jan', 'Jan/2026', 'Janeiro', 1, 'I - durante três anos, pelo menos, o condenado por crime a que a lei comina pena de reclusão por tempo não inferior, no mínimo, a dez anos, se na sentença...', '§ 4º Na hipótese da reincidência descrita no § 3º deste artigo, o administrador, direta ou indiretamente responsável pela infração cometida, será interditado para o exercício do comércio pelo período de 5 cinco anos. (Incluído pela Lei nº 15.358, de 2026)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15358.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 103', '(Parágrafo único. Nos crimes praticados no âmbito de violência doméstica e familiar contra a mulher, a ofendida decai do direito de queixa... Incluído pela Lei nº 15.438, de 16 de janeiro de 2026)', 2026, 'Jan', 'Jan/2026', 'Janeiro', 1, 'Dispositivo sem previsão explícita de exceção em violência doméstica e familiar.', 'Parágrafo único. Nos crimes praticados no âmbito de violência doméstica e familiar contra a mulher, a ofendida decai do direito de queixa ou de representação se não o exerce no prazo de 6 (seis) meses. (Incluído pela Lei nº 15.438, de 2026)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15438.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 121-A', '(Matar mulher por razões da condição do sexo feminino - Feminicídio autônomo com pena de reclusão de 20 a 40 anos. Incluído pela Lei nº 14.994, de 9 de outubro de 2024)', 2024, 'Out', 'Out/2024', 'Outubro', 10, 'Art. 121, § 2º, VI - Feminicídio como qualificadora com pena de 12 a 30 anos.', 'Art. 121-A. Matar mulher por razões da condição do sexo feminino: Pena - reclusão, de 20 (vinte) a 40 (quarenta) anos. (Incluído pela Lei nº 14.994, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 147-B', '(Violência psicológica contra a mulher - Aumento de pena. Alterado pela Lei nº 14.994, de 9 de outubro de 2024)', 2024, 'Out', 'Out/2024', 'Outubro', 10, 'Pena - reclusão, de 6 (seis) meses a 2 (dois) anos, e multa, se a conduta não constitui crime mais grave.', 'Pena - reclusão, de 2 (dois) a 5 (cinco) anos, e multa, se a conduta não constitui crime mais grave. (Redação dada pela Lei nº 14.994, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 146', '(§ 1º A pena aplica-se cumulativamente e em dobro. Alterado pela Lei nº 14.811, de 15 de janeiro de 2024 - Medidas de proteção à criança e adolescente)', 2024, 'Jan', 'Jan/2024', 'Janeiro', 1, 'Pena - detenção, de um a seis meses, ou multa.', '§ 1º Aplica-se a pena em dobro se o crime é cometido em ambiente escolar ou contra menor de 14 (quatorze) anos. (Redação dada pela Lei nº 14.811, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14811.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 155', '(§ 4º-B e § 4º-C - Furto eletrônico ou mediante fraude cibernética. Alterado pela Lei nº 14.811, de 15 de janeiro de 2024)', 2024, 'Jan', 'Jan/2024', 'Janeiro', 1, 'Pena - reclusão, de 2 (dois) a 8 (oito) anos, e multa.', '§ 4º-B A pena é de reclusão, de 4 (quatro) a 8 (oito) anos, e multa, se o furto mediante fraude é cometido por meio de dispositivo eletrônico ou informático.', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14811.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 157', '(§ 2º, incisos II e VII - Roubo com arma branca ou concurso de pessoas. Lei nº 13.964, de 24 de dezembro de 2019)', 2019, 'Dez', 'Dez/2019', 'Dezembro', 12, 'A pena aumenta-se de um terço até metade.', '§ 2º-A A pena aumenta-se de 2/3 (dois terços): I – se a violência ou ameaça é exercida com emprego de arma de fogo.', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13964.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cp', 'Art. 171', '(§ 4º Aplica-se a pena em dobro se o crime for cometido contra idoso ou vulnerável. Lei nº 14.155, de 27 de maio de 2021)', 2021, 'Mai', 'Mai/2021', 'Maio', 5, 'Pena aumentada de um terço se o crime é cometido em detrimento de entidade de direito público.', '§ 4º A pena aumenta-se de 1/3 (um terço) ao dobro, se o crime é cometido contra idoso ou vulnerável, considerada a relevância do resultado gravoso.', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14155.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cc', 'Art. 1815', '(Indignidade para herança no feminicídio e crimes contra mulher. Redação dada pela Lei nº 14.994, de 9 de outubro de 2024)', 2024, 'Out', 'Out/2024', 'Outubro', 10, 'Art. 1.815. A exclusão do herdeiro ou legatário, em qualquer desses casos de indignidade, será declarada por sentença.', 'Art. 1.815. O herdeiro ou legatário que incorrer em qualquer das hipóteses de indignidade previstas neste Código perderá o direito à herança independentemente de sentença penal condenatória transitada em julgado. § 3º Na hipótese do inciso I do caput do art. 1.814 deste Código, a ação declaratória de indignidade poderá ser proposta pelo Ministério Público. (Redação dada pela Lei nº 14.994, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cc', 'Art. 1814', '(Causa de exclusão da sucessão por feminicídio ou homicídio doloso contra cônjuge. Alterado pela Lei nº 14.994, de 9 de outubro de 2024)', 2024, 'Out', 'Out/2024', 'Outubro', 10, 'I - que houverem sido autores, co-autores ou partícipes de homicídio doloso, ou tentativa deste...', 'Art. 1.814. São excluídos da sucessão os herdeiros ou legatários: I - que houverem sido autores, coautores ou partícipes de homicídio doloso, feminicídio ou de tentativa deste, contra a pessoa de cuja sucessão se tratar, seu cônjuge, companheiro, ascendente ou descendente. (Redação dada pela Lei nº 14.994, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cc', 'Art. 853-A', '(Contrato de administração de garantias fiduciárias. Incluído pela Lei nº 14.711, de 30 de outubro de 2023)', 2023, 'Out', 'Out/2023', 'Outubro', 10, 'Dispositivo sem previsão explícita de agente de garantia fiduciária.', 'Art. 853-A. Qualquer garantia poderá ser constituída ou levada a registro em nome de agente de garantia, que atuará em favor dos credores da obrigação garantida ou de seus sucessores. (Incluído pela Lei nº 14.711, de 2023)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14711.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cc', 'Art. 1367', '(Execução de garantias fiduciárias supervenientes. Redação dada pela Lei nº 14.711, de 30 de outubro de 2023)', 2023, 'Out', 'Out/2023', 'Outubro', 10, 'A propriedade fiduciária em garantia de bens móveis ou imóveis submete-se à disciplina das respectivas leis especiais...', 'Art. 1.367. A propriedade fiduciária em garantia de bens móveis ou imóveis submete-se à disciplina das respectivas leis especiais e às normas gerais deste Código. (Redação dada pela Lei nº 14.711, de 2023)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14711.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cc', 'Art. 1417-A', '(Promessa de permuta e eficácia real equivalente à promessa de compra e venda. Incluído pela Lei nº 14.711, de 30 de outubro de 2023)', 2023, 'Out', 'Out/2023', 'Outubro', 10, 'Dispositivo sem previsão legal explícita de permuta com direito real.', 'Art. 1.417-A. À promessa de permuta de bens imóveis aplica-se o disposto no art. 1.417 e no art. 1.418 deste Código. (Incluído pela Lei nº 14.711, de 2023)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14711.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cc', 'Art. 1225', '(Direitos reais sobre imissão provisória na posse em desapropriação. Incluído pela Lei nº 14.620, de 13 de julho de 2023)', 2023, 'Jul', 'Jul/2023', 'Julho', 7, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 1.225. São direitos reais: XIV - os direitos oriundos da imissão provisória na posse, quando concedida à União, aos Estados, ao Distrito Federal, aos Municípios ou às suas entidades delegadas e a respectiva cessão e promessa de cessão. (Incluído pela Lei nº 14.620, de 2023)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14620.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cpp', 'Art. 300-A', '(Identificação de perfil genético por DNA de investigados por crimes sexuais. Incluído pela Lei nº 15.280, de 5 de dezembro de 2025)', 2025, 'Dez', 'Dez/2025', 'Dezembro', 12, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 300-A. O investigado por crimes contra a dignidade sexual, quando preso cautelarmente, e o condenado pelos mesmos crimes deverão ser submetidos obrigatoriamente à identificação do perfil genético por extração de DNA (ácido desoxirribonucleico), por técnica adequada e indolor, por ocasião do ingresso no estabelecimento prisional. (Incluído pela Lei nº 15.280, de 2025)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15280.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cpp', 'Art. 394-A', '(Prioridade especial nos procedimentos que apuram violência contra mulher e feminicídio. Redação dada pela Lei nº 14.994, de 9 de outubro de 2024)', 2024, 'Out', 'Out/2024', 'Outubro', 10, 'Art. 394-A. Os processos que apuram a prática de crime hediondo terão prioridade de tramitação em todas as instâncias.', 'Art. 394-A. Terão prioridade de tramitação em todas as instâncias os processos que apuram: I - a prática de crime hediondo; II - os crimes previstos no art. 121-A do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), e outros crimes praticados contra a mulher por razões da condição do sexo feminino. (Redação dada pela Lei nº 14.994, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cpp', 'Art. 615', '(Critério de desempate favorável ao réu no julgamento de habeas corpus e recursos. Redação dada pela Lei nº 14.836, de 8 de abril de 2024)', 2024, 'Abr', 'Abr/2024', 'Abril', 4, '§ 1º Em caso de empate, prevalecerá a decisão mais favorável ao réu.', 'Art. 615. O tribunal decidirá por maioria de votos. § 1º Em caso de empate de votos no julgamento de habeas corpus ou de recurso em matéria penal, havendo ou não tomado parte no julgamento o presidente do colegiado, prevalecerá a decisão mais favorável ao réu ou ao paciente, e será proclamado imediatamente esse resultado. (Redação dada pela Lei nº 14.836, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14836.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cpp', 'Art. 112', '(Exame criminológico e regras para progressão de regime. Alterado pela Lei nº 14.843, de 11 de abril de 2024)', 2024, 'Abr', 'Abr/2024', 'Abril', 4, 'Requisitos puramente formais e de bom comportamento carcerário.', 'Art. 112. A pena privativa de liberdade será executada em forma progressiva... § 1º Em todos os casos, o apenado somente terá direito à progressão de regime se ostentar boa conduta carcerária, comprovada pelo diretor do estabelecimento, e pelos resultados do exame criminológico. (Redação dada pela Lei nº 14.843, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14843.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ctb', 'Art. 303', '(Lesão corporal culposa praticada na direção de veículo automotor contra mulher por razões de sexo. Alterado pela Lei nº 14.994, de 9 de outubro de 2024)', 2024, 'Out', 'Out/2024', 'Outubro', 10, 'Pena - detenção, de seis meses a dois anos e suspensão ou proibição de se obter a permissão ou a habilitação para dirigir veículo automotor.', 'Art. 303. Praticar lesão corporal culposa na direção de veículo automotor: Pena - detenção, de 6 (seis) meses a 2 (dois) anos e suspensão ou proibição de se obter a permissão ou a habilitação para dirigir veículo automotor. § 2º A pena privativa de liberdade é de reclusão de 2 (dois) a 5 (cinco) anos, sem prejuízo das outras penas previstas neste artigo, se o agente conduz veículo automotor sob a influência de álcool ou qualquer outra substância psicoativa que determine dependência e do crime resultar lesão corporal de natureza grave ou gravíssima de mulher por razões da condição de sexo feminino. (Incluído pela Lei nº 14.994, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ctb', 'Art. 148', '(Validade da CNH diferenciada por faixa etária. Alterado pela Lei nº 14.904, de 27 de junho de 2024)', 2024, 'Jun', 'Jun/2024', 'Junho', 6, 'A habilitação será apurada por meio de exames que deverão ser realizados junto ao órgão ou entidade executivos do Estado ou do Distrito Federal.', 'Art. 148. Os exames de habilitação, as avaliações psicológicas e os exames de aptidão física e mental serão realizados na forma regulamentada pelo Contran. § 2º A Carteira Nacional de Habilitação, expedida em modelo único e de acordo com as especificações do Contran, terá validade de: I – 10 (dez) anos, para condutores com menos de 50 (cinquenta) anos de idade; II – 5 (cinco) anos, para condutores com idade igual ou superior a 50 (cinquenta) anos e inferior a 70 (setenta) anos; III – 3 (três) anos, para condutores com idade igual ou superior a 70 (setenta) anos. (Redação dada pela Lei nº 14.904, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14904.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ctb', 'Art. 329-A', '(Faixa de pedestres em áreas escolares e penalidades de trânsito relacionadas. Incluído pela Lei nº 14.811, de 15 de janeiro de 2024)', 2024, 'Jan', 'Jan/2024', 'Janeiro', 1, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 329-A. Deixar o órgão ou entidade de trânsito de instalar ou manter, em condições de visibilidade e segurança, faixa de pedestres e sinalização específica de advertência nas proximidades de estabelecimentos de educação infantil, de ensino fundamental, de ensino médio, de ensino superior, e de instituições de longa permanência para idosos. (Incluído pela Lei nº 14.811, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14811.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ctb', 'Art. 256', '(Sistema de pontuação - Limite elevado de 20 para 40 pontos. Alterado pela Lei nº 14.071, de 13 de outubro de 2020)', 2021, 'Abr', 'Abr/2021', 'Abril', 4, 'O condutor que acumular 20 (vinte) pontos terá a habilitação suspensa.', 'Art. 256. O condutor que acumular 40 (quarenta) pontos no período de 12 (doze) meses terá suspensão do direito de dirigir. § 1º O condutor que acumular 30 (trinta) pontos no período de 12 (doze) meses terá suspensão do direito de dirigir, quando possuir 2 (duas) ou mais infrações gravíssimas. § 2º O condutor que acumular 20 (vinte) pontos no período de 12 (doze) meses terá suspensão do direito de dirigir, quando for reincidente em infração gravíssima. (Redação dada pela Lei nº 14.071, de 2020)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/lei/l14071.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ctb', 'Art. 261', '(Suspensão do direito de dirigir - Proporcionalidade na penalidade. Alterado pela Lei nº 14.071, de 13 de outubro de 2020)', 2021, 'Abr', 'Abr/2021', 'Abril', 4, 'A penalidade de suspensão do direito de dirigir será aplicada, nos casos previstos neste Código, pelo prazo mínimo de um mês até no máximo de um ano.', 'Art. 261. A penalidade de suspensão do direito de dirigir será aplicada, nos casos previstos neste Código, pelo prazo mínimo de 6 (seis) meses e máximo de 12 (doze) meses, excetuadas as hipóteses em que o prazo é fixado de forma expressa. (Redação dada pela Lei nº 14.071, de 2020)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/lei/l14071.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ctb', 'Art. 306', '(Embriaguez ao volante - Pena aumentada. Alterado pela Lei nº 14.071, de 13 de outubro de 2020)', 2021, 'Abr', 'Abr/2021', 'Abril', 4, 'Pena - detenção, de seis meses a três anos, multa e suspensão ou proibição de se obter a permissão ou a habilitação para dirigir veículo automotor.', 'Art. 306. Conduzir veículo automotor com capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência: Pena - detenção, de 6 (seis) meses a 3 (três) anos, multa e suspensão ou proibição de se obter a permissão ou a habilitação para dirigir veículo automotor. § 3º O Contran disporá sobre a equivalência entre os distintos testes de alcoolemia ou toxicológicos para efeito de caracterização do crime tipificado neste artigo. (Redação dada pela Lei nº 14.071, de 2020)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/lei/l14071.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cf88', 'Art. 156-A', '(Imposto sobre Bens e Serviços - IBS. Incluído pela Emenda Constitucional nº 132, de 20 de dezembro de 2023)', 2023, 'Dez', 'Dez/2023', 'Dezembro', 12, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 156-A. Lei complementar instituirá imposto sobre bens e serviços de competência compartilhada entre Estados, Distrito Federal e Municípios. (Incluído pela EC nº 132, de 2023)', 'https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc132.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cf88', 'Art. 195', '(Contribuição sobre Bens e Serviços - CBS. Alterado pela Emenda Constitucional nº 132, de 20 de dezembro de 2023)', 2023, 'Dez', 'Dez/2023', 'Dezembro', 12, 'A seguridade social será financiada por toda a sociedade...', 'Art. 195. V - sobre bens e serviços, nos termos de lei complementar. (Incluído pela EC nº 132, de 2023)', 'https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc132.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cf88', 'Art. 198', '(Piso salarial nacional dos profissionais de enfermagem. Alterado pela Emenda Constitucional nº 127, de 22 de dezembro de 2022)', 2022, 'Dez', 'Dez/2022', 'Dezembro', 12, 'Sem previsão de piso salarial para enfermagem na Constituição.', 'Art. 198. § 13. A lei federal estabelecerá o piso salarial nacional dos profissionais de enfermagem, observado o disposto no § 12 deste artigo. (Incluído pela EC nº 127, de 2022)', 'https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc127.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cf88', 'Art. 6º', '(Alimentação e transporte como direitos sociais fundamentais. Redação atualizada pela Emenda Constitucional nº 90, de 15 de setembro de 2015)', 2015, 'Set', 'Set/2015', 'Setembro', 9, 'São direitos sociais a educação, a saúde, a alimentação, o trabalho, a moradia, o lazer, a segurança...', 'Art. 6º São direitos sociais a educação, a saúde, a alimentação, o trabalho, a moradia, o transporte, o lazer, a segurança, a previdência social, a proteção à maternidade e à infância, a assistência aos desamparados. (Redação dada pela EC nº 90, de 2015)', 'https://www.planalto.gov.br/ccivil_03/constituicao/emendas/emc/emc90.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cpc', 'Art. 489', '(Fundamentação das decisões judiciais — elementos essenciais da sentença. Redação dada pela Lei nº 14.995, de 10 de outubro de 2024)', 2024, 'Out', 'Out/2024', 'Outubro', 10, 'São elementos essenciais da sentença: I – o relatório...', 'Art. 489. São elementos essenciais da sentença: § 1º Não se considera fundamentada qualquer decisão judicial, seja ela interlocutória, sentença ou acórdão, que: V - se limitar a invocar precedente ou enunciado de súmula, sem identificar seus fundamentos determinantes nem demonstrar que o caso sob julgamento se ajusta àqueles fundamentos. (Redação dada pela Lei nº 14.995, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14995.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cpc', 'Art. 1.003', '(Prazo de interposição de recurso - contagem em dias úteis. Redação original da Lei nº 13.105, de 16 de março de 2015)', 2015, 'Mar', 'Mar/2015', 'Março', 3, 'Prazos processuais contados em dias corridos (CPC/1973).', 'Art. 1.003. O prazo para interposição de recurso conta-se da data em que os advogados, a sociedade de advogados, a Advocacia Pública, a Defensoria Pública ou o Ministério Público são intimados da decisão. § 5º Excetuados os embargos de declaração, o prazo para interpor os recursos e para responder-lhes é de 15 (quinze) dias. (Incluído pela Lei nº 13.105, de 2015)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cpc', 'Art. 219', '(Contagem de prazos processuais apenas em dias úteis. Incluído pela Lei nº 13.105, de 16 de março de 2015)', 2015, 'Mar', 'Mar/2015', 'Março', 3, 'CPC/1973 contava prazos em dias corridos.', 'Art. 219. Na contagem de prazo em dias, estabelecido por lei ou pelo juiz, computar-se-ão somente os dias úteis. (Incluído pela Lei nº 13.105, de 2015)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('clt', 'Art. 461', '(Igualdade salarial entre homens e mulheres. Alterado pela Lei nº 14.611, de 3 de julho de 2023)', 2023, 'Jul', 'Jul/2023', 'Julho', 7, 'Sendo idêntica a função, a todo trabalho de igual valor, prestado ao mesmo empregador...', 'Art. 461. Sendo idêntica a função, a todo trabalho de igual valor, prestado ao mesmo empregador, no mesmo estabelecimento empresarial, corresponderá igual salário, sem distinção de sexo, etnia, nacionalidade ou idade. § 6º Na hipótese de discriminação por motivo de sexo, raça, etnia, origem ou idade, o pagamento das diferenças salariais devidas ao empregado discriminado não afasta seu direito de ação de indenização por danos morais. § 7º Sem prejuízo do disposto no § 6º, no caso de infração ao previsto neste artigo, a multa de que trata o art. 510 desta Consolidação corresponderá a 10 (dez) vezes o valor do novo salário devido pelo empregador ao empregado discriminado. (Redação dada pela Lei nº 14.611, de 2023)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14611.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('clt', 'Art. 75-B', '(Teletrabalho e trabalho remoto — regulamentação. Alterado pela Lei nº 14.442, de 2 de setembro de 2022)', 2022, 'Set', 'Set/2022', 'Setembro', 9, 'Considera-se teletrabalho a prestação de serviços preponderantemente fora das dependências do empregador...', 'Art. 75-B. Considera-se teletrabalho ou trabalho remoto a prestação de serviços fora das dependências do empregador, de maneira preponderante ou não, com a utilização de tecnologias de informação e de comunicação, que, por sua natureza, não configure trabalho externo. § 1º O comparecimento, ainda que de modo habitual, às dependências do empregador para a realização de atividades específicas não descaracteriza o regime de teletrabalho. (Redação dada pela Lei nº 14.442, de 2022)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/lei/l14442.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('clt', 'Art. 611-A', '(Prevalência do negociado sobre o legislado — Reforma Trabalhista. Incluído pela Lei nº 13.467, de 13 de julho de 2017)', 2017, 'Jul', 'Jul/2017', 'Julho', 7, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 611-A. A convenção coletiva e o acordo coletivo de trabalho têm prevalência sobre a lei quando, entre outros, dispuserem sobre: I - pacto quanto à jornada de trabalho; II - banco de horas anual; III - intervalo intrajornada. (Incluído pela Lei nº 13.467, de 2017)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13467.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cdc', 'Art. 54-A', '(Prevenção e tratamento do superendividamento do consumidor. Incluído pela Lei nº 14.181, de 1º de julho de 2021)', 2021, 'Jul', 'Jul/2021', 'Julho', 7, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 54-A. Este Capítulo dispõe sobre a prevenção do superendividamento da pessoa natural e sobre o crédito responsável, e tem o objetivo de promover o acesso ao crédito de forma responsável. (Incluído pela Lei nº 14.181, de 2021)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14181.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cdc', 'Art. 54-D', '(Vedações às práticas de crédito irresponsável. Incluído pela Lei nº 14.181, de 1º de julho de 2021)', 2021, 'Jul', 'Jul/2021', 'Julho', 7, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 54-D. Na oferta de crédito, previamente à contratação, o fornecedor ou o intermediário deverá, entre outras condutas: I - informar e esclarecer adequadamente o consumidor sobre a natureza e a modalidade do crédito; II - avaliar de forma responsável e leal as condições do consumidor. (Incluído pela Lei nº 14.181, de 2021)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14181.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cdc', 'Art. 104-A', '(Processo de repactuação de dívidas do consumidor superendividado. Incluído pela Lei nº 14.181, de 1º de julho de 2021)', 2021, 'Jul', 'Jul/2021', 'Julho', 7, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 104-A. A requerimento do consumidor superendividado pessoa natural, o juiz poderá instaurar processo de repactuação de dívidas, com vistas à realização de audiência conciliatória, presidida por ele ou por conciliador credenciado no juízo. (Incluído pela Lei nº 14.181, de 2021)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14181.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ctn', 'Art. 155-A', '(Parcelamento - Revogação de ofício e consequências. Alterado pela LC nº 104, de 10 de janeiro de 2001)', 2001, 'Jan', 'Jan/2001', 'Janeiro', 1, 'Sem previsão específica de parcelamento no CTN.', 'Art. 155-A. O parcelamento será concedido na forma e condição estabelecidas em lei específica. § 1º Salvo disposição de lei em contrário, o parcelamento do crédito tributário não exclui a incidência de juros e multas. (Incluído pela LC nº 104, de 2001)', 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp104.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('eca', 'Art. 244-C', '(Intimidação sistemática virtual — cyberbullying como crime. Incluído pela Lei nº 14.811, de 15 de janeiro de 2024)', 2024, 'Jan', 'Jan/2024', 'Janeiro', 1, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 244-C. Intimidar sistematicamente, por qualquer meio, inclusive virtual (cyberbullying), mediante violência física ou psicológica, atos de intimidação, de humilhação ou de discriminação: Pena - reclusão, de 2 (dois) a 4 (quatro) anos, e multa. (Incluído pela Lei nº 14.811, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14811.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('eca', 'Art. 244-B', '(Intimidação sistemática — bullying tipificado como crime. Incluído pela Lei nº 14.811, de 15 de janeiro de 2024)', 2024, 'Jan', 'Jan/2024', 'Janeiro', 1, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 244-B. Intimidar sistematicamente, individualmente ou em grupo, mediante violência física ou psicológica, uma ou mais pessoas, de modo intencional e repetitivo: Pena - multa, se a conduta não constituir crime mais grave. (Incluído pela Lei nº 14.811, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14811.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('eca', 'Art. 241-D', '(Aliciamento de criança online — tipificação penal com aumento de pena. Alterado pela Lei nº 14.811, de 15 de janeiro de 2024)', 2024, 'Jan', 'Jan/2024', 'Janeiro', 1, 'Pena – reclusão, de 1 (um) a 3 (três) anos, e multa.', 'Art. 241-D. Aliciar, assediar, instigar ou constranger, por qualquer meio de comunicação, criança, com o fim de com ela praticar ato libidinoso: Pena – reclusão, de 2 (dois) a 5 (cinco) anos. (Redação dada pela Lei nº 14.811, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14811.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lep', 'Art. 112', '(Exame criminológico obrigatório para progressão de regime. Alterado pela Lei nº 14.843, de 11 de abril de 2024)', 2024, 'Abr', 'Abr/2024', 'Abril', 4, 'Progressão baseada apenas em bom comportamento e tempo cumprido.', 'Art. 112. A pena privativa de liberdade será executada em forma progressiva com a transferência para regime menos rigoroso. § 1º Em todos os casos, o apenado somente terá direito à progressão de regime se ostentar boa conduta carcerária, comprovada pelo diretor do estabelecimento, e pelos resultados do exame criminológico. (Redação dada pela Lei nº 14.843, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14843.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lep', 'Art. 52', '(Regime disciplinar diferenciado - RDD. Alterado pela Lei nº 13.964, de 24 de dezembro de 2019)', 2019, 'Dez', 'Dez/2019', 'Dezembro', 12, 'RDD com duração máxima de 360 dias.', 'Art. 52. A prática de fato previsto como crime doloso constitui falta grave e, quando ocasionar subversão da ordem ou disciplina internas, sujeitará o preso provisório, ou condenado, nacional ou estrangeiro, sem prejuízo da sanção penal, ao regime disciplinar diferenciado. § 1º O regime disciplinar diferenciado terá duração máxima de até 2 (dois) anos, sem prejuízo de repetição da sanção. (Redação dada pela Lei nº 13.964, de 2019)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13964.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lmp', 'Art. 12-C', '(Afastamento imediato do agressor pelo delegado. Alterado pela Lei nº 14.994, de 9 de outubro de 2024)', 2024, 'Out', 'Out/2024', 'Outubro', 10, 'Art. 12-C. Verificada a existência de risco atual ou iminente...', 'Art. 12-C. Verificada a existência de risco atual ou iminente à vida ou à integridade física e psicológica da mulher, o agressor será imediatamente afastado do lar, domicílio ou local de convivência com a ofendida. § 1º O afastamento de que trata o caput deste artigo poderá ser determinado pelo delegado de polícia ou pelo policial. (Redação dada pela Lei nº 14.994, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lmp', 'Art. 24-A', '(Descumprimento de medida protetiva — Pena aumentada. Alterado pela Lei nº 14.994, de 9 de outubro de 2024)', 2024, 'Out', 'Out/2024', 'Outubro', 10, 'Pena – detenção, de 3 (três) meses a 2 (dois) anos.', 'Art. 24-A. Descumprir decisão judicial que defere medidas protetivas de urgência previstas nesta Lei: Pena – reclusão, de 1 (um) a 3 (três) anos. § 1º A conduta descrita no caput será processada de ofício. (Redação dada pela Lei nº 14.994, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lmp', 'Art. 10-A', '(Direito de a vítima ter advogado em todos os atos processuais. Incluído pela Lei nº 13.836, de 4 de junho de 2019)', 2019, 'Jun', 'Jun/2019', 'Junho', 6, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 10-A. É direito da mulher em situação de violência doméstica e familiar o atendimento policial e pericial especializado, ininterrupto e prestado por servidores - preferencialmente do sexo feminino. (Incluído pela Lei nº 13.836, de 2019)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13836.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ld', 'Art. 28', '(Porte pessoal de maconha — Definição de quantidade para uso próprio. Alterado pela Lei nº 14.195, de 26 de agosto de 2021)', 2021, 'Ago', 'Ago/2021', 'Agosto', 8, 'Quem adquirir, guardar, tiver em depósito, transportar ou trouxer consigo drogas para consumo pessoal...', 'Art. 28. Quem adquirir, guardar, tiver em depósito, transportar ou trouxer consigo, para consumo pessoal, drogas sem autorização ou em desacordo com determinação legal ou regulamentar será submetido às seguintes penas: I - advertência; II - prestação de serviços à comunidade; III - medida educativa. (Redação dada pela Lei nº 14.195, de 2021)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14195.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ld', 'Art. 33', '(Tráfico de drogas — Pacote Anticrime. Alterado pela Lei nº 13.964, de 24 de dezembro de 2019)', 2019, 'Dez', 'Dez/2019', 'Dezembro', 12, 'Pena - reclusão de 5 (cinco) a 15 (quinze) anos e pagamento de multa.', 'Art. 33. Importar, exportar, remeter, preparar, produzir, fabricar, adquirir, vender, expor à venda, oferecer, ter em depósito, transportar, trazer consigo, guardar, prescrever, ministrar, entregar a consumo ou fornecer drogas: Pena - reclusão de 5 (cinco) a 15 (quinze) anos e pagamento de 500 (quinhentos) a 1.500 (mil e quinhentos) dias-multa. (Redação dada pela Lei nº 13.964, de 2019)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13964.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('loc', 'Art. 2º', '(Pena aumentada para organização criminosa armada. Alterado pela Lei nº 13.964, de 24 de dezembro de 2019)', 2019, 'Dez', 'Dez/2019', 'Dezembro', 12, 'Pena - reclusão, de 3 (três) a 8 (oito) anos, e multa.', 'Art. 2º Promover, constituir, financiar ou integrar, pessoalmente ou por interposta pessoa, organização criminosa: Pena - reclusão, de 3 (três) a 8 (oito) anos, e multa. § 2º Se há emprego de arma de fogo, a pena é aumentada de metade. § 8º As lideranças de organizações criminosas armadas ou que tenham armas à disposição deverão iniciar o cumprimento da pena em estabelecimentos penais de segurança máxima. (Redação dada pela Lei nº 13.964, de 2019)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13964.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('loc', 'Art. 3º-A', '(Juiz das garantias no âmbito de investigações de organização criminosa. Incluído pela Lei nº 13.964, de 24 de dezembro de 2019)', 2019, 'Dez', 'Dez/2019', 'Dezembro', 12, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 3º-A. O processo penal terá estrutura acusatória, vedadas a iniciativa do juiz na fase de investigação e a substituição da atuação probatória do órgão de acusação. (Incluído pela Lei nº 13.964, de 2019)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13964.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lindb', 'Art. 20', '(Decisões com base em valores jurídicos abstratos devem considerar consequências práticas. Incluído pela Lei nº 13.655, de 25 de abril de 2018)', 2018, 'Abr', 'Abr/2018', 'Abril', 4, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 20. Nas esferas administrativa, controladora e judicial, não se decidirá com base em valores jurídicos abstratos sem que sejam consideradas as consequências práticas da decisão. Parágrafo único. A motivação demonstrará a necessidade e a adequação da medida imposta ou da invalidação de ato, contrato, ajuste, processo ou norma administrativa. (Incluído pela Lei nº 13.655, de 2018)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13655.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lindb', 'Art. 21', '(Regime de transição para novas interpretações administrativas. Incluído pela Lei nº 13.655, de 25 de abril de 2018)', 2018, 'Abr', 'Abr/2018', 'Abril', 4, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 21. A decisão que, nas esferas administrativa, controladora ou judicial, decretar a invalidação de ato, contrato, ajuste, processo ou norma administrativa deverá indicar de modo expresso suas consequências jurídicas e administrativas. Parágrafo único. A decisão a que se refere o caput deste artigo deverá, quando for o caso, indicar as condições para que a regularização ocorra de modo proporcional e equânime. (Incluído pela Lei nº 13.655, de 2018)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13655.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lch', 'Art. 1º', '(Feminicídio incluído no rol de crimes hediondos. Alterado pela Lei nº 14.994, de 9 de outubro de 2024)', 2024, 'Out', 'Out/2024', 'Outubro', 10, 'Art. 1º São considerados hediondos: I - homicídio (art. 121), quando praticado em atividade típica de grupo de extermínio...', 'Art. 1º São considerados hediondos os seguintes crimes: I - homicídio (art. 121), quando praticado em atividade típica de grupo de extermínio; I-A - feminicídio (art. 121-A); I-B - lesão corporal seguida de morte praticada contra a mulher por razões da condição do sexo feminino. (Redação dada pela Lei nº 14.994, de 2024)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2024/lei/l14994.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lch', 'Art. 2º', '(Regime de cumprimento de pena para crimes hediondos — Pacote Anticrime. Alterado pela Lei nº 13.964, de 24 de dezembro de 2019)', 2019, 'Dez', 'Dez/2019', 'Dezembro', 12, 'A progressão de regime, no caso dos condenados por crimes hediondos, dar-se-á após o cumprimento de 2/5 da pena.', 'Art. 2º. § 2º A progressão de regime, no caso dos condenados pelos crimes previstos neste artigo, dar-se-á após o cumprimento de: I - 40% da pena, se o apenado não for reincidente nem tiver sido associado a organização criminosa; II - 50% da pena, se o apenado for reincidente; III - 60% da pena, se for reincidente específico; IV - 70% da pena, se tiver sido condenado por comando de organização criminosa estruturada. (Redação dada pela Lei nº 13.964, de 2019)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13964.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lia', 'Art. 11', '(Atos de improbidade que atentam contra princípios da administração — Exigência de dolo. Alterado pela Lei nº 14.230, de 25 de outubro de 2021)', 2021, 'Out', 'Out/2021', 'Outubro', 10, 'Constitui ato de improbidade administrativa que atenta contra os princípios da administração pública...', 'Art. 11. Constitui ato de improbidade administrativa que atenta contra os princípios da administração pública a ação ou omissão dolosa que viole os deveres de honestidade, de imparcialidade e de legalidade. (Redação dada pela Lei nº 14.230, de 2021)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14230.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lia', 'Art. 17', '(Ação de improbidade — Legitimidade exclusiva do Ministério Público. Alterado pela Lei nº 14.230, de 25 de outubro de 2021)', 2021, 'Out', 'Out/2021', 'Outubro', 10, 'A ação principal será proposta pelo Ministério Público ou pela pessoa jurídica interessada.', 'Art. 17. A ação para a aplicação das sanções de que trata esta Lei será proposta pelo Ministério Público e seguirá o procedimento comum previsto na Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil). (Redação dada pela Lei nº 14.230, de 2021)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14230.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('nll', 'Art. 178', '(Aplicação imediata da nova lei de licitações — Revogação da Lei 8.666. A partir de 30 de dezembro de 2023)', 2023, 'Dez', 'Dez/2023', 'Dezembro', 12, 'Lei 8.666/1993 vigente para todos os contratos.', 'Art. 178. Revogam-se: I - a Lei nº 8.666, de 21 de junho de 1993; II - a Lei nº 10.520, de 17 de julho de 2002; III - os arts. 1º a 47-A da Lei nº 12.462, de 4 de agosto de 2011. (Incluído pela Lei nº 14.133, de 2021, com vigência plena a partir de 30/12/2023)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/L14133.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('nll', 'Art. 75', '(Contratação direta — Dispensa e inexigibilidade. Incluído pela Lei nº 14.133, de 1º de abril de 2021)', 2021, 'Abr', 'Abr/2021', 'Abril', 4, 'Dispensa nos termos do art. 24 da Lei 8.666/93.', 'Art. 75. É dispensável a licitação: I - para contratação que envolva valores inferiores a R$ 100.000,00 (cem mil reais), no caso de obras e serviços de engenharia; II - para contratação que envolva valores inferiores a R$ 50.000,00 (cinquenta mil reais), no caso de outros serviços e compras. (Incluído pela Lei nº 14.133, de 2021)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/L14133.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lgpd', 'Art. 52', '(Sanções administrativas — ANPD pode aplicar multa de até 2% do faturamento. Vigência a partir de 1º de agosto de 2021)', 2021, 'Ago', 'Ago/2021', 'Agosto', 8, 'Sanções sem vigência definida.', 'Art. 52. Os agentes de tratamento de dados, em razão das infrações cometidas às normas previstas nesta Lei, ficam sujeitos às seguintes sanções administrativas aplicáveis pela autoridade nacional: II - multa simples, de até 2% do faturamento da pessoa jurídica, limitada, no total, a R$ 50.000.000,00 por infração. (Vigência a partir de 01/08/2021)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lgpd', 'Art. 55-A', '(Autoridade Nacional de Proteção de Dados — ANPD. Incluído pela Lei nº 13.853, de 8 de julho de 2019)', 2019, 'Jul', 'Jul/2019', 'Julho', 7, 'ANPD prevista mas sem regulamentação específica.', 'Art. 55-A. Fica criada, sem aumento de despesa, a Autoridade Nacional de Proteção de Dados - ANPD, órgão da administração pública federal, integrante da Presidência da República. (Incluído pela Lei nº 13.853, de 2019)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13853.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('l8112', 'Art. 117', '(Proibições ao servidor — vedação de acumulação com empresas. Alterado pela Lei nº 13.303, de 30 de junho de 2016)', 2016, 'Jun', 'Jun/2016', 'Junho', 6, 'Art. 117. Ao servidor é proibido: X - participar de gerência ou administração de sociedade privada...', 'Art. 117. Ao servidor é proibido: X - participar de gerência ou administração de sociedade privada, personificada ou não personificada, exercer o comércio, exceto na qualidade de acionista, cotista ou comanditário. (Redação dada pela Lei nº 13.303, de 2016)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('l8112', 'Art. 143', '(Processo Administrativo Disciplinar — Instauração obrigatória. Regulamentado pela Lei nº 8.112, de 11 de dezembro de 1990)', 1990, 'Dez', 'Dez/1990', 'Dezembro', 12, 'Sem especificação anterior.', 'Art. 143. A autoridade que tiver ciência de irregularidade no serviço público é obrigada a promover a sua apuração imediata, mediante sindicância ou processo administrativo disciplinar, assegurada ao acusado ampla defesa. (Incluído pela Lei nº 8.112, de 1990)', 'https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ei', 'Art. 19', '(Proteção contra violência doméstica à pessoa idosa. Alterado pela Lei nº 14.423, de 22 de julho de 2022)', 2022, 'Jul', 'Jul/2022', 'Julho', 7, 'Os casos de suspeita ou confirmação de violência serão notificados compulsoriamente pelos serviços de saúde.', 'Art. 19. Os casos de suspeita ou confirmação de violência praticada contra a pessoa idosa serão objeto de notificação compulsória pelos serviços de saúde públicos e privados à autoridade sanitária, bem como serão obrigatoriamente comunicados por eles a quaisquer dos seguintes órgãos: I - autoridade policial; II - Ministério Público; III - Conselho Municipal do Idoso; IV - Conselho Estadual do Idoso; V - Conselho Nacional do Idoso. (Redação dada pela Lei nº 14.423, de 2022)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/lei/l14423.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ei', 'Art. 96', '(Discriminação de pessoa idosa com pena aumentada. Alterado pela Lei nº 14.423, de 22 de julho de 2022)', 2022, 'Jul', 'Jul/2022', 'Julho', 7, 'Pena – reclusão de 6 (seis) meses a 1 (um) ano e multa.', 'Art. 96. Discriminar pessoa idosa, impedindo ou dificultando seu acesso a operações bancárias, aos meios de transporte, ao direito de contratar ou por qualquer outro meio ou instrumento necessário ao exercício da cidadania: Pena – reclusão de 6 (seis) meses a 1 (um) ano e multa. § 1º Na mesma pena incorre quem desdenhar, humilhar, menosprezar ou discriminar pessoa idosa, por qualquer motivo. (Redação dada pela Lei nº 14.423, de 2022)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/lei/l14423.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('epd', 'Art. 88', '(Prioridade na tramitação processual à pessoa com deficiência. Incluído pela Lei nº 13.146, de 6 de julho de 2015)', 2015, 'Jul', 'Jul/2015', 'Julho', 7, 'Dispositivo incluído pela primeira vez (inédito).', 'Art. 88. Praticar, induzir ou incitar discriminação de pessoa em razão de sua deficiência: Pena - reclusão, de 1 (um) a 3 (três) anos, e multa. § 1º Aumenta-se a pena em 1/3 (um terço) se a vítima encontrar-se sob cuidado e responsabilidade do agente. (Incluído pela Lei nº 13.146, de 2015)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ed', 'Art. 6º', '(Critérios para porte de arma de fogo — restrição de acesso. Alterado pela Lei nº 14.785, de 27 de dezembro de 2023)', 2023, 'Dez', 'Dez/2023', 'Dezembro', 12, 'É proibido o porte de arma de fogo em todo o território nacional, salvo para os casos previstos em legislação própria.', 'Art. 6º É proibido o porte de arma de fogo em todo o território nacional, salvo para os casos previstos em legislação própria e para: I – os integrantes das Forças Armadas; II – os integrantes dos órgãos de segurança pública; III – os agentes de segurança privada e os guardas municipais que preencherem os requisitos legais. (Redação dada pela Lei nº 14.785, de 2023)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14785.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ed', 'Art. 17', '(Comércio ilegal de arma de fogo — Pena aumentada. Alterado pela Lei nº 13.964, de 24 de dezembro de 2019)', 2019, 'Dez', 'Dez/2019', 'Dezembro', 12, 'Pena – reclusão, de 4 (quatro) a 8 (oito) anos, e multa.', 'Art. 17. Adquirir, alugar, receber, transportar, conduzir, ocultar, ter em depósito, desmontar, montar, remontar, adulterar, vender, expor à venda, ou de qualquer forma utilizar, em proveito próprio ou alheio, no exercício de atividade comercial ou industrial, arma de fogo, acessório ou munição: Pena – reclusão, de 6 (seis) a 12 (doze) anos, e multa. (Redação dada pela Lei nº 13.964, de 2019)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13964.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('eoab', 'Art. 7º', '(Direitos do advogado — Prerrogativas profissionais. Alterado pela Lei nº 13.245, de 12 de janeiro de 2016)', 2016, 'Jan', 'Jan/2016', 'Janeiro', 1, 'São direitos do advogado: XXI – assistir a seus clientes investigados durante a apuração de infrações...', 'Art. 7º São direitos do advogado: XXI - assistir a seus clientes investigados durante a apuração de infrações, sob pena de nulidade absoluta do respectivo interrogatório ou depoimento e, subsequentemente, de todos os elementos investigatórios e probatórios dele decorrentes ou derivados, direta ou indiretamente. (Redação dada pela Lei nº 13.245, de 2016)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13245.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('ce', 'Art. 326', '(Crimes eleitorais — fake news e desinformação eleitoral. Alterado pela Lei nº 14.192, de 4 de agosto de 2021)', 2021, 'Ago', 'Ago/2021', 'Agosto', 8, 'Sem previsão específica sobre violência política de gênero.', 'Art. 326. Assediar, constranger, humilhar, perseguir ou ameaçar, por qualquer meio, candidata a cargo eletivo ou detentora de mandato eletivo, utilizando-se de menosprezo ou discriminação à condição de mulher ou à sua cor, raça ou etnia, com a finalidade de impedir ou de dificultar a sua campanha eleitoral ou o desempenho de seu mandato eletivo: Pena - reclusão, de 1 (um) a 4 (quatro) anos, e multa. (Incluído pela Lei nº 14.192, de 2021)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14192.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cflor', 'Art. 68', '(Regularização de áreas consolidadas até 22 de julho de 2008. Incluído pela Lei nº 12.651, de 25 de maio de 2012)', 2012, 'Mai', 'Mai/2012', 'Maio', 5, 'Código Florestal anterior (Lei 4.771/1965).', 'Art. 68. Os proprietários ou possuidores de imóveis rurais que realizaram supressão de vegetação nativa respeitando os percentuais de Reserva Legal previstos pela legislação em vigor à época em que ocorreu a supressão são dispensados de promover a recomposição, compensação ou regeneração. (Incluído pela Lei nº 12.651, de 2012)', 'https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12651compilado.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cpm', 'Art. 9º', '(Definição de crime militar em tempo de paz. Alterado pela Lei nº 13.491, de 13 de outubro de 2017)', 2017, 'Out', 'Out/2017', 'Outubro', 10, 'Consideram-se crimes militares os crimes em espécie definidos neste Código...', 'Art. 9º Consideram-se crimes militares, em tempo de paz: II – os crimes previstos neste Código e os previstos na legislação penal, quando praticados: a) por militar em situação de atividade ou assemelhado, em lugar sujeito à administração militar. (Redação dada pela Lei nº 13.491, de 2017)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13491.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('cppm', 'Art. 18', '(Competência da Justiça Militar — Extensão pela Lei 13.491/2017. Alterado pela Lei nº 13.491, de 13 de outubro de 2017)', 2017, 'Out', 'Out/2017', 'Outubro', 10, 'Competência original do CPPM para crimes militares em espécie.', 'A Justiça Militar é competente para processar e julgar os crimes militares definidos no art. 9º do Código Penal Militar, incluindo as condutas previstas na legislação penal comum quando praticadas nas condições do art. 9º. (Alterado pela Lei nº 13.491, de 2017)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13491.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('laa', 'Art. 9º', '(Decretar medida de privação de liberdade em manifesta desconformidade com a lei. Incluído pela Lei nº 13.869, de 5 de setembro de 2019)', 2019, 'Set', 'Set/2019', 'Setembro', 9, 'Lei anterior revogada (Lei nº 4.898/1965).', 'Art. 9º Decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais: Pena - detenção, de 1 (um) a 4 (quatro) anos, e multa. (Incluído pela Lei nº 13.869, de 2019)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/L13869.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lca', 'Art. 29', '(Crimes contra a fauna — matar, perseguir, caçar. Redação original da Lei nº 9.605, de 12 de fevereiro de 1998)', 1998, 'Fev', 'Fev/1998', 'Fevereiro', 2, 'Legislação esparsa anterior.', 'Art. 29. Matar, perseguir, caçar, apanhar, utilizar espécimes da fauna silvestre, nativos ou em rota migratória, sem a devida permissão, licença ou autorização da autoridade competente: Pena - detenção de 6 (seis) meses a 1 (um) ano, e multa. (Incluído pela Lei nº 9.605, de 1998)', 'https://www.planalto.gov.br/ccivil_03/leis/L9605.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lrac', 'Art. 20', '(Injúria racial equiparada a racismo. Alterado pela Lei nº 14.532, de 11 de janeiro de 2023)', 2023, 'Jan', 'Jan/2023', 'Janeiro', 1, 'Injúria racial prevista no Código Penal (art. 140, § 3º).', 'Art. 20. Praticar, induzir ou incitar a discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional: Pena: reclusão de 2 (dois) a 5 (cinco) anos, e multa. § 2º-A Injuriar alguém, ofendendo-lhe a dignidade ou o decoro, em razão de raça, cor, etnia ou procedência nacional: Pena: reclusão, de 2 (dois) a 5 (cinco) anos, e multa. (Redação dada pela Lei nº 14.532, de 2023)', 'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14532.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lje', 'Art. 61', '(Infrações de menor potencial ofensivo — conceito atualizado. Alterado pela Lei nº 11.313, de 28 de junho de 2006)', 2006, 'Jun', 'Jun/2006', 'Junho', 6, 'Consideram-se infrações penais de menor potencial ofensivo as contravenções penais e os crimes a que a lei comine pena máxima não superior a 1 ano.', 'Art. 61. Consideram-se infrações penais de menor potencial ofensivo, para os efeitos desta Lei, as contravenções penais e os crimes a que a lei comine pena máxima não superior a 2 (dois) anos, cumulada ou não com multa. (Redação dada pela Lei nº 11.313, de 2006)', 'https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11313.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('mci', 'Art. 19', '(Responsabilidade do provedor de aplicações por conteúdo de terceiros. Incluído pela Lei nº 12.965, de 23 de abril de 2014)', 2014, 'Abr', 'Abr/2014', 'Abril', 4, 'Sem regulamentação específica sobre responsabilidade de provedores.', 'Art. 19. Com o intuito de assegurar a liberdade de expressão e impedir a censura, o provedor de aplicações de internet somente poderá ser responsabilizado civilmente por danos decorrentes de conteúdo gerado por terceiros se, após ordem judicial específica, não tomar as providências para tornar indisponível o conteúdo apontado como infringente. (Incluído pela Lei nº 12.965, de 2014)', 'https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lf', 'Art. 6º', '(Regime de recuperação judicial simplificado para ME e EPP. Alterado pela Lei nº 14.112, de 24 de dezembro de 2020)', 2020, 'Dez', 'Dez/2020', 'Dezembro', 12, 'Sem previsão de regime simplificado.', 'A Lei nº 14.112/2020 reformou profundamente a Lei de Falências, incluindo o parcelamento de créditos tributários pelo devedor em recuperação judicial, aprimorando o regime de recuperação extrajudicial, e prevendo o mecanismo de DIP financing (financiamento ao devedor em posse). (Alterado pela Lei nº 14.112, de 2020)', 'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/lei/l14112.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lbps', 'Art. 25', '(Pensão por morte — Fim da vitaliciedade para cônjuge jovem. Alterado pela Lei nº 13.135, de 17 de junho de 2015)', 2015, 'Jun', 'Jun/2015', 'Junho', 6, 'Pensão por morte vitalícia para cônjuge independente de idade.', 'Art. 25. A pensão por morte será devida ao conjunto dos dependentes do segurado que falecer, aposentado ou não. § 2º-B A duração da cota de pensão por morte para o cônjuge, companheiro ou companheira será calculada de acordo com sua expectativa de sobrevida no momento do óbito do instituidor. (Redação dada pela Lei nº 13.135, de 2015)', 'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13135.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('li', 'Art. 62', '(Despejo — Liminar em ação de despejo por falta de pagamento. Alterado pela Lei nº 12.112, de 9 de dezembro de 2009)', 2009, 'Dez', 'Dez/2009', 'Dezembro', 12, 'Liminar de despejo restrita a hipóteses específicas.', 'Art. 62. Nas ações de despejo fundadas na falta de pagamento de aluguel e acessórios da locação, de aluguel provisório, de diferenças de aluguéis, ou somente de quaisquer dos acessórios da locação, observar-se-á o seguinte: I – o pedido de rescisão da locação poderá ser cumulado com o pedido de cobrança dos aluguéis e acessórios da locação, devendo ser apresentado, com a inicial, cálculo discriminado do valor do débito. (Redação dada pela Lei nº 12.112, de 2009)', 'https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/lei/l12112.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('eme', 'Art. 18-A', '(MEI — Limites de faturamento e atividades. Alterado pela LC nº 188, de 4 de janeiro de 2022)', 2022, 'Jan', 'Jan/2022', 'Janeiro', 1, 'MEI com faturamento máximo de R$ 81.000,00.', 'Art. 18-A. O Microempreendedor Individual - MEI poderá optar pelo recolhimento dos impostos e contribuições abrangidos pelo Simples Nacional em valores fixos mensais. § 1º Para os efeitos desta Lei Complementar, considera-se MEI o empresário individual ou o empreendedor que exerça atividades de industrialização, comercialização e prestação de serviços no âmbito rural, que tenha auferido receita bruta, no ano-calendário anterior, de até R$ 81.000,00. (Redação dada pela LC nº 188, de 2022)', 'https://www.planalto.gov.br/ccivil_03/leis/LCP/Lcp188.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('llav', 'Art. 1º', '(Lavagem de dinheiro — Crime antecedente ampliado para qualquer infração penal. Alterado pela Lei nº 12.683, de 9 de julho de 2012)', 2012, 'Jul', 'Jul/2012', 'Julho', 7, 'Rol taxativo de crimes antecedentes para lavagem de dinheiro.', 'Art. 1º Ocultar ou dissimular a natureza, origem, localização, disposição, movimentação ou propriedade de bens, direitos ou valores provenientes, direta ou indiretamente, de infração penal. Pena: reclusão, de 3 (três) a 10 (dez) anos, e multa. (Redação dada pela Lei nº 12.683, de 2012)', 'https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12683.htm', NULL);
INSERT INTO public.scraped_article_updates (lei_id, artigo, motivo, ano, mes, mes_ano, mes_completo, mes_index, texto_antigo, texto_novo, link_lei, data_completa) VALUES ('lpaf', 'Art. 50', '(Motivação obrigatória dos atos administrativos. Incluído pela Lei nº 9.784, de 29 de janeiro de 1999)', 1999, 'Jan', 'Jan/1999', 'Janeiro', 1, 'Sem legislação federal específica de processo administrativo.', 'Art. 50. Os atos administrativos deverão ser motivados, com indicação dos fatos e dos fundamentos jurídicos, quando: I - neguem, limitem ou afetem direitos ou interesses; II - imponham ou agravem deveres, encargos ou sanções; III - decidam processos administrativos de concurso ou seleção pública. (Incluído pela Lei nº 9.784, de 1999)', 'https://www.planalto.gov.br/ccivil_03/leis/l9784.htm', NULL);
